:root {
  --green-900: #163022;
  --green-700: #1f4d36;
  --green-500: #2f7a52;
  --green-100: #e8f3ec;
  --cream: #f8f4ed;
  --brown-900: #3a2a1f;
  --brown-700: #5a4635;
  --text: #1f1f1f;
  --muted: #6a6a6a;
  --white: #fff;
  --shadow: 0 10px 30px rgba(32, 28, 24, 0.08);
  --radius: 18px;
}
* { box-sizing: border-box; }
html, body { margin: 0; padding: 0; font-family: 'Inter', system-ui, sans-serif; color: var(--text); background: var(--cream); }
a { color: inherit; text-decoration: none; }
img { max-width: 100%; display: block; }
.container { width: min(1120px, 92vw); margin: 0 auto; }
.site-header { position: sticky; top: 0; z-index: 20; background: rgba(248,244,237,.92); backdrop-filter: blur(8px); border-bottom: 1px solid #e7e0d4; }
.nav { display:flex; align-items:center; justify-content:space-between; padding: 14px 0; gap: 16px; }
.brand { display:flex; align-items:center; gap:10px; font-weight:800; color:var(--green-900); }
.bean { width:36px; height:36px; border-radius:50%; background: radial-gradient(circle at 30% 30%, #77b788, #2f7a52 70%); box-shadow: inset 0 -6px 10px rgba(0,0,0,.18); }
.nav-links { display:flex; gap: 18px; font-weight:600; }
.nav-links a { padding:8px 12px; border-radius: 999px; }
.nav-links a.active, .nav-links a:hover { background: var(--green-100); color: var(--green-700); }
.cta-btn { background: var(--green-700); color: var(--white); border:none; padding:10px 16px; border-radius:999px; font-weight:700; cursor:pointer; }
.hero { padding: 64px 0 40px; display:grid; grid-template-columns: 1.1fr .9fr; gap: 28px; align-items:center; }
.hero h1 { font-family: 'DM Sans', Inter, sans-serif; font-size: clamp(2rem, 4vw, 3.5rem); line-height:1.06; margin:0 0 14px; color: var(--green-900); }
.hero p { color: var(--brown-700); font-size: 1.05rem; }
.hero-card { background: var(--white); border-radius: var(--radius); box-shadow: var(--shadow); padding: 14px; }
.photo { border-radius: 14px; min-height: 300px; background: linear-gradient(135deg, #a37c5d, #6e4f3b 60%, #d7c3ad); position:relative; overflow:hidden; }
.photo:after { content:''; position:absolute; inset:0; background: radial-gradient(circle at 70% 20%, rgba(255,255,255,.34), transparent 34%); }
.section { padding: 36px 0; }
.section h2 { font-family:'DM Sans', Inter, sans-serif; font-size: clamp(1.5rem, 2.8vw, 2.2rem); margin: 0 0 14px; color: var(--brown-900); }
.cards { display:grid; grid-template-columns: repeat(3,minmax(0,1fr)); gap:16px; }
.card { background: var(--white); border-radius: var(--radius); box-shadow: var(--shadow); padding: 16px; }
.pill { display:inline-block; padding: 6px 10px; border-radius: 999px; background: var(--green-100); color: var(--green-700); font-weight:700; font-size:.84rem; }
.footer { background:#efe7da; margin-top:52px; border-top:1px solid #dfd6c7; }
.footer-grid { display:grid; grid-template-columns: repeat(4,minmax(0,1fr)); gap:24px; padding: 30px 0; }
.footer h4 { margin:0 0 12px; font-size:1rem; }
.footer ul { margin:0; padding:0; list-style:none; display:grid; gap:8px; color:#4f4b47; }
.footer-bottom { padding: 14px 0 24px; color:#736d66; font-size:.9rem; }
.mobile-accordion-toggle { display:none; }
.cookie { position: fixed; left: 20px; right: 20px; bottom: 20px; background: #163022; color:#f0f8f3; border-radius:14px; padding:14px; display:flex; gap:14px; align-items:center; justify-content:space-between; z-index:40; box-shadow: var(--shadow); }
.cookie.hidden { display:none; }
.tabs { display:flex; gap:8px; flex-wrap:wrap; margin-bottom:14px; }
.tab-btn { border:none; background:#ece6da; border-radius:999px; padding:8px 12px; font-weight:700; cursor:pointer; }
.tab-btn.active { background: var(--green-700); color:#fff; }
.tab-panel { display:none; }
.tab-panel.active { display:block; }
.carousel { position:relative; }
.track-wrap { overflow:hidden; }
.track { display:flex; gap:14px; transition: transform .35s ease; }
.slide { min-width: 220px; background:#fff; border-radius:14px; box-shadow:var(--shadow); padding:12px; }
.car-btn { position:absolute; top:40%; transform:translateY(-50%); border:none; width:38px; height:38px; border-radius:50%; background:#fff; box-shadow:var(--shadow); cursor:pointer; }
.car-btn.prev { left:-10px; }
.car-btn.next { right:-10px; }
.layout { display:grid; grid-template-columns: 240px 1fr; gap:20px; }
.sidebar { background:#fff; border-radius:14px; box-shadow:var(--shadow); padding:14px; align-self:start; position:sticky; top:90px; }
.sidebar ul { list-style:none; padding:0; margin:0; display:grid; gap:8px; }
.sidebar a { display:block; padding:8px; border-radius:10px; }
.sidebar a:hover { background:var(--green-100); }
.store-shell { display:grid; grid-template-columns: 360px 1fr; gap:20px; }
.panel, .map { background:#fff; border-radius:16px; box-shadow:var(--shadow); padding:14px; }
.search { width:100%; border:1px solid #ddd; border-radius:10px; padding:10px; }
.suggestions { margin-top:8px; display:grid; gap:6px; }
.suggestion { padding:8px 10px; background:#f6f2ea; border-radius:8px; cursor:pointer; }
.toggle-group { display:flex; gap:8px; margin:10px 0; }
.toggle-group button { flex:1; border:none; padding:8px; border-radius:10px; background:#eee6db; font-weight:700; }
.toggle-group button.active { background:var(--green-700); color:#fff; }
.filter-panel { display:none; margin:8px 0 10px; padding:10px; border-radius:10px; background:#f4efe6; }
.filter-panel.open { display:block; }
@media (max-width: 960px) {
  .hero { grid-template-columns: 1fr; }
  .cards { grid-template-columns: 1fr 1fr; }
  .layout, .store-shell { grid-template-columns: 1fr; }
  .sidebar { position: static; }
  .footer-grid { grid-template-columns: 1fr 1fr; }
}
@media (max-width: 720px) {
  .nav { flex-wrap:wrap; }
  .nav-links { width:100%; overflow:auto; }
  .cards { grid-template-columns: 1fr; }
  .footer-grid { grid-template-columns: 1fr; }
  .footer-col { border-bottom:1px solid #d7cdbe; padding: 8px 0; }
  .mobile-accordion-toggle { display:flex; width:100%; justify-content:space-between; align-items:center; background:none; border:none; font:inherit; font-weight:700; padding:6px 0; }
  .footer-col ul { display:none; padding: 8px 0 12px; }
  .footer-col.open ul { display:grid; }
}
EOF

cat > /app/output/assets/app.js <<'EOF'
(function(){
  const cookie = document.querySelector('[data-cookie]');
  const agree = document.querySelector('[data-cookie-agree]');
  if (cookie && agree) agree.addEventListener('click', ()=> cookie.classList.add('hidden'));

  document.querySelectorAll('[data-accordion]').forEach(col=>{
    const btn = col.querySelector('.mobile-accordion-toggle');
    if (!btn) return;
    btn.addEventListener('click', ()=> col.classList.toggle('open'));
  });

  const tabBtns = document.querySelectorAll('[data-tab-btn]');
  if (tabBtns.length) {
    tabBtns.forEach(btn=>btn.addEventListener('click', ()=>{
      const key = btn.dataset.tabBtn;
      document.querySelectorAll('[data-tab-btn]').forEach(b=>b.classList.remove('active'));
      document.querySelectorAll('[data-tab-panel]').forEach(p=>p.classList.remove('active'));
      btn.classList.add('active');
      const panel = document.querySelector(`[data-tab-panel="${key}"]`);
      if (panel) panel.classList.add('active');
    }));
  }

  document.querySelectorAll('[data-carousel]').forEach(car=>{
    const track = car.querySelector('.track');
    const slides = car.querySelectorAll('.slide');
    const prev = car.querySelector('.prev');
    const next = car.querySelector('.next');
    let index = 0;
    const visible = () => Math.max(1, Math.floor(car.querySelector('.track-wrap').offsetWidth / 234));
    const update = () => {
      const max = Math.max(0, slides.length - visible());
      index = Math.max(0, Math.min(index, max));
      track.style.transform = `translateX(${-index*234}px)`;
    };
    prev && prev.addEventListener('click', ()=>{ index -= 1; update(); });
    next && next.addEventListener('click', ()=>{ index += 1; update(); });
    window.addEventListener('resize', update);
    update();
  });

  const search = document.querySelector('[data-store-search]');
  if (search) {
    const suggestions = document.querySelector('[data-suggestions]');
    const mapText = document.querySelector('[data-map-text]');
    const results = document.querySelector('[data-results]');
    const places = ['Seattle, WA', 'Portland, OR', 'Denver, CO', 'Austin, TX', 'Chicago, IL'];
    const render = (q='') => {
      const filtered = places.filter(p=>p.toLowerCase().includes(q.toLowerCase()));
      suggestions.innerHTML = filtered.map(p=>`<div class="suggestion">${p}</div>`).join('');
      results.innerHTML = filtered.map((p,i)=>`<div class="card" style="margin-bottom:8px"><strong>${p}</strong><p style="margin:.3rem 0;color:#666">${(i+1)*0.6} mi · Open until 9:00 PM</p></div>`).join('') || '<p>No stores found.</p>';
      mapText.textContent = filtered.length ? `Showing ${filtered.length} stores near ${filtered[0]}` : 'No matching map results';
      suggestions.querySelectorAll('.suggestion').forEach(el=>el.addEventListener('click', ()=>{ search.value = el.textContent; render(el.textContent); }));
    };
    search.addEventListener('input', e=>render(e.target.value));
    render('');

    const filterBtn = document.querySelector('[data-filter-btn]');
    const filterPanel = document.querySelector('[data-filter-panel]');
    filterBtn && filterBtn.addEventListener('click', ()=> filterPanel.classList.toggle('open'));

    const orderBtns = document.querySelectorAll('[data-order-type]');
    orderBtns.forEach(btn=>btn.addEventListener('click', ()=>{
      orderBtns.forEach(b=>b.classList.remove('active'));
      btn.classList.add('active');
      const type = btn.dataset.orderType;
      const marker = type === 'delivery' ? 'Delivery-ready stores highlighted' : 'Pickup-ready stores highlighted';
      mapText.textContent = marker;
    }));
  }
})();
EOF

